;   Menu_Mode0CH2 (JSR $C2:D5C6), Menu_ShopListClose (JSR $C2:D5E3), Menu_Mode0CH5 (JSR $C2:D638),
;   Menu_Mode0CH3 (JSR $C2:D676), Menu_Mode0CH4 (JSR $C2:D6B0), Menu_Mode0CH6 (JSR $C2:D6D9, JSR
